// quick reproduction using csv-core directly
use csv_core::{Reader, ReaderBuilder, ReadRecordResult, Terminator};

fn parse_all(rdr: &mut Reader, data: &[u8]) -> (Vec<Vec<String>>, u64) {
    let mut recs = vec![];
    let mut out = [0u8; 1024];
    let mut ends = [0usize; 16];
    let mut input = data;
    loop {
        let (res, nin, nout, nend) = rdr.read_record(input, &mut out, &mut ends);
        input = &input[nin..];
        match res {
            ReadRecordResult::Record => {
                let mut rec = vec![];
                let mut start = 0;
                for &e in &ends[..nend] {
                    rec.push(String::from_utf8_lossy(&out[start..e]).into_owned());
                    start = e;
                }
                recs.push(rec);
            }
            ReadRecordResult::InputEmpty => {
                assert!(input.is_empty());
            }
            ReadRecordResult::End => break,
            r => panic!("unexpected {:?}", r),
        }
    }
    (recs, rdr.line())
}

fn main() {
    let data = b"a\nb,1|# note\nc,2|";
    // DFA
    let mut rdr = ReaderBuilder::new()
        .terminator(Terminator::Any(b'|'))
        .comment(Some(b'#'))
        .build();
    let (recs, line) = parse_all(&mut rdr, data);
    println!("DFA whole: {:?} line={}", recs, line);

    // NFA
    let mut rdr = ReaderBuilder::new()
        .terminator(Terminator::Any(b'|'))
        .comment(Some(b'#'))
        .nfa(true)
        .build();
    let (recs, line) = parse_all(&mut rdr, data);
    println!("NFA whole: {:?} line={}", recs, line);

    // DFA byte-at-a-time
    let mut rdr = ReaderBuilder::new()
        .terminator(Terminator::Any(b'|'))
        .comment(Some(b'#'))
        .build();
    let mut recs = vec![];
    let mut out = [0u8; 1024];
    let mut ends = [0usize; 16];
    let mut i = 0;
    let data = &data[..];
    loop {
        let chunk = if i < data.len() { &data[i..i + 1] } else { &[][..] };
        let (res, nin, nout, nend) = rdr.read_record(chunk, &mut out, &mut ends);
        i += nin;
        match res {
            ReadRecordResult::Record => {
                let mut rec = vec![];
                let mut start = 0;
                for &e in &ends[..nend] {
                    rec.push(String::from_utf8_lossy(&out[start..e]).into_owned());
                    start = e;
                }
                recs.push(rec);
            }
