        assert_eq!(rec, StringRecord::from(vec!["c", "2"]));
        assert_eq!(&newpos(13, 3, 1), rec.position().unwrap());

        assert!(!rdr.read_record(&mut rec).unwrap());
        assert_eq!(&newpos(17, 3, 2), rdr.position());
    }

