                assert_eq!(3, len);
            }
            ref x => panic!("expected UnequalLengths, got {:?}", x),
        }
        // Reading can continue after the error.
        assert!(!rdr.read_byte_record(&mut rec).unwrap());
    }

    // Test that a UTF-8 error carries the position of the offending
